import {el,button,link,announce,focusHeading,practiceFrame,optionsList,recommendations} from './ui.js';
export const tracks=[{id:'phishing',name:'Phishing',icon:'✉'},{id:'payments',name:'Payment fraud',icon:'₹'},{id:'impersonation',name:'Impersonation',icon:'◎'},{id:'malware',name:'Malware',icon:'⌘'},{id:'adware',name:'Adware & scareware',icon:'▧'}];
export function createSimulator(scenarios,scams,openArticle){
let host,routeBefore;let track='all',level='all',run=[],answers=[],index=0,pending=null,view='lobby';
const name=id=>tracks.find(t=>t.id===id)?.name??'Mixed drill';
function start(items){run=items;answers=[];index=0;pending=null;view='practice';render(true);}
function lobby(){host.replaceChildren();const toolbar=el('div','lab-toolbar');toolbar.append(el('div','terminal-label','> SELECT TRAINING MODULE'));if(run.length&&answers.length<run.length)toolbar.append(button('Resume current drill →','button secondary',()=>{view='practice';render(true);}));host.append(toolbar);const filters=el('div','chips');filters.setAttribute('aria-label','Simulation categories');[{id:'all',name:'All threats'},...tracks].forEach(t=>{const b=button(t.name,'chip'+(track===t.id?' active':''),()=>{track=t.id;lobby();});b.setAttribute('aria-pressed',String(track===t.id));filters.append(b);});host.append(filters);const set=scenarios.filter(s=>track==='all'||s.track===track);const banner=el('div','drill-banner');const copy=el('div');copy.append(el('span','overline',track==='all'?'THE COMPLETE DRILL':name(track).toUpperCase()+' DRILL'),el('h2','',track==='all'?'One inbox. Twelve ways to be fooled.':'Build your '+name(track).toLowerCase()+' instincts.'),el('p','','Practise this set in order, or open a single mission below. Your debrief will show the warning signs and topics to revisit.'));banner.append(copy,button(`Start ${set.length}-scenario drill →`,'button',()=>start(set)));host.append(banner);const levels=el('div','level-row');levels.append(el('span','small-note','Browse by difficulty:'));['all','Beginner','Intermediate','Advanced'].forEach(d=>{const b=button(d==='all'?'All levels':d,'chip'+(level===d?' active':''),()=>{level=d;lobby();});b.setAttribute('aria-pressed',String(level===d));levels.append(b);});host.append(levels);const list=set.filter(s=>level==='all'||s.difficulty===level);host.append(el('p','library-count',`${list.length} missions available · Self-paced · Fictional practice`));const grid=el('div','mission-grid');list.forEach(s=>{const card=el('article','mission-card');const preview=el('div','mission-preview preview-'+s.screen);if(s.image){const image=el('img');image.src=s.image;image.alt=`Fictional ${s.screen} practice: ${s.title}`;image.loading='lazy';preview.append(image);}else preview.append(el('span','preview-symbol',tracks.find(t=>t.id===s.track).icon),el('span','preview-channel',s.screen.toUpperCase()+' / SIMULATION'),el('div','preview-message',s.fictionalMessage.split('\n')[0]));const content=el('div','mission-content');const meta=el('div','mission-meta');meta.append(el('span','tag',name(s.track)),el('span','tiny',s.difficulty));content.append(meta,el('h3','',s.title),el('p','',`${s.screen==='chat'?'WhatsApp-style chat':s.screen==='sms'?'SMS message':s.screen==='email'?'Email attachment':s.screen==='installer'?'App installation':s.screen==='permissions'?'Extension permissions':s.screen==='payment'?'Payment screen':'Browser screen'} · 1 decision`),button('Open simulation ↗','button secondary',()=>start([s])));card.append(preview,content);grid.append(card);});if(!list.length)grid.append(el('p','empty','No missions at this level in this category. Choose another level.'));host.append(grid,el('p','small-note','All screens are fictional reconstructions. No real message, file, payment or download is involved.'));
}
function evidence(s){const figure=el('figure','evidence-screen');if(s.image){const image=el('img','evidence-image');image.src=s.image;image.alt='Fictional practice screen. Complete text is provided below.';figure.append(image,button('View full-size screen ↗','evidence-zoom',()=>{const dialog=el('dialog','image-dialog');dialog.setAttribute('aria-label','Full-size fictional practice screen');const img=el('img');img.src=s.image;img.alt=s.fictionalMessage;dialog.append(button('Close screen ×','button secondary',()=>dialog.close()),img);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal();}));const text=el('details','transcript');text.append(el('summary','','Read the screen as text'),el('p','',s.fictionalMessage));figure.append(text);}else{const mock=el('div','native-screen native-'+s.screen);mock.append(el('div','mock-bar',s.screen==='browser'?'● ● ●   demo.example':s.screen==='email'?'Inbox / Message':s.screen==='installer'?'App installation':s.screen==='permissions'?'Extension permissions':'9:41                         ▮▮ ▰'));const head=el('div','mock-header');head.append(el('span','mock-avatar',s.sender[0]),el('strong','',s.sender));mock.append(head,el('div','mock-message',s.fictionalMessage),el('div','mock-composer',s.screen==='chat'?'Message…   ▷':'FICTIONAL / NO REAL ACTIONS'));figure.append(mock);}figure.append(el('figcaption','','Fictional training example · Inspect first, then decide.'));return figure;}
function practice(focus){const s=run[index],answer=answers[index];const body=practiceFrame(host,index+1,run.length,name(s.track).toUpperCase()+' / TRAINING');body.classList.add('lab-practice');const step=el('div','step-label');step.append(el('span','tag',s.difficulty),button('← Mission library','reset-button',()=>{view='lobby';render(true);}));body.append(step,el('h2','',s.title),el('p','scenario-context',s.context));const split=el('div','scenario-split');split.append(evidence(s));const decision=el('div','decision-panel');decision.append(el('span','overline','YOUR MOVE'),el('h3','','What would you do next?'),el('p','small-note','Select one response. You can change it before submitting.'),optionsList(s.options,answer??pending,answer?s.correctOptionId:null,id=>{pending=id;render();host.querySelectorAll('.option')[s.options.findIndex(o=>o.id===id)].focus();}));if(answer){const safe=answer===s.correctOptionId;const feedback=el('div',`feedback ${safe?'':'risky'}`);feedback.setAttribute('role','status');feedback.append(el('h3','',safe?'Safe move. Here is why.':'A trap worth recognising.'),el('p','',s.explanation),el('h4','','Warning signs revealed'));const ul=el('ul','revealed-signs');s.warningSigns.forEach((text,i)=>ul.append(el('li','',`${String(i+1).padStart(2,'0')} / ${text}`)));feedback.append(ul);const selected=s.options.find(o=>o.id===answer);if(selected?.rationale)feedback.append(el('p','choice-reason','Your response: '+selected.rationale));decision.append(feedback);}const next=button(answer?(index===run.length-1?'View debrief →':'Next mission →'):'Lock in my response','button',()=>{if(answers[index]){if(index===run.length-1)view='summary';else index++;pending=null;render(true);}else if(pending){answers[index]=pending;render();announce(answers[index]===s.correctOptionId?'Safe move. Warning signs revealed.':'Response recorded. Review the safer choice.');host.querySelector('.feedback').scrollIntoView({block:'nearest'});}});next.disabled=!answer&&!pending;decision.append(next,button('Restart this drill','reset-button',()=>start(run)));split.append(decision);body.append(split);if(focus)focusHeading(host);}
function summary(){host.replaceChildren();const score=run.reduce((n,s,i)=>n+Number(answers[i]===s.correctOptionId),0);const box=el('div','practice-shell summary');box.append(el('span','tag green','MISSION DEBRIEF'),el('h2','','Better instincts start with practice.'));const total=el('div','score-display',String(score));total.append(el('span','',` / ${run.length} safer choices`));box.append(total,el('p','','This is a practice result, not a guarantee of real-world security. Take these warning signs into your next message, download or payment.'));const stats=el('div','track-results');tracks.forEach(t=>{const ids=run.map((s,i)=>s.track===t.id?i:-1).filter(i=>i>=0);if(ids.length)stats.append(el('div','',`${t.name}: ${ids.filter(i=>answers[i]===run[i].correctOptionId).length}/${ids.length}`));});box.append(stats);const missed=run.filter((s,i)=>answers[i]!==s.correctOptionId);box.append(el('h3','',missed.length?'Strengthen these topics':'Keep your skills sharp'));recommendations(box,(missed.length?missed:run.slice(0,3)).map(s=>s.relatedScamId),scams,openArticle);const actions=el('div','actions');actions.append(button('Choose another mission','button',()=>{view='lobby';render(true);}),button('Replay this drill','button secondary',()=>start(run)),link('Take the safety quiz','#quiz','button secondary'));box.append(actions);run.forEach((s,i)=>{const detail=el('details','review');detail.append(el('summary','',`${answers[i]===s.correctOptionId?'✓':'↺'} ${s.title}`),el('p','',s.explanation));box.append(detail);});host.append(box);focusHeading(host);}
function render(focus=false){if(view==='lobby'){lobby();if(focus)host.scrollIntoView({block:'start'});}else if(view==='practice')practice(focus);else summary();}
return{mount(container,route){host=container;if(route!==routeBefore){track=tracks.some(t=>t.id===route)?route:'all';view='lobby';routeBefore=route;}render();},reset(){track='all';level='all';run=[];answers=[];index=0;pending=null;view='lobby';routeBefore=undefined;}};
}
